using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using AuthService.Data;using AuthService.DTOs;using AuthService.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;namespace AuthService.Services;public class BusinessException(string m):Exception(m);public interface IAuthService{Task<AuthResponse>Register(RegisterRequest r,CancellationToken c);Task<AuthResponse>Login(LoginRequest r,CancellationToken c);}public class AuthService(AuthDbContext db,IConfiguration cfg):IAuthService{public async Task<AuthResponse>Register(RegisterRequest r,CancellationToken c){var role=r.Role.ToUpperInvariant();if(role!="ADMIN"&&role!="USER")throw new BusinessException("Role must be ADMIN or USER.");if(await db.Users.AnyAsync(x=>x.Username==r.Username,c))throw new BusinessException("Username already exists.");var u=new User{Username=r.Username,PasswordHash=BCrypt.Net.BCrypt.HashPassword(r.Password),Role=role,CreatedAt=DateTime.UtcNow};db.Users.Add(u);await db.SaveChangesAsync(c);return Token(u);}public async Task<AuthResponse>Login(LoginRequest r,CancellationToken c){var u=await db.Users.FirstOrDefaultAsync(x=>x.Username==r.Username&&x.IsActive,c);if(u==null||!BCrypt.Net.BCrypt.Verify(r.Password,u.PasswordHash))throw new BusinessException("Invalid username or password.");return Token(u);}AuthResponse Token(User u){var exp=DateTime.UtcNow.AddMinutes(int.Parse(cfg["Jwt:ExpiryMinutes"]!));var claims=new[]{new Claim(JwtRegisteredClaimNames.Sub,u.UserId.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.NameIdentifier,u.UserId.ToString()),new Claim(ClaimTypes.Role,u.Role)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(cfg["Jwt:Key"]!));var t=new JwtSecurityToken(claims:claims,expires:exp,signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256));return new(new JwtSecurityTokenHandler().WriteToken(t),u.UserId,u.Username,u.Role,exp);}}